<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {runnerConnections,type Connection,type ConnectionConfig,type ConnectionList} from '@/api/runnerConnections'
import RunnerSettingsNav from '@/components/RunnerSettingsNav.vue'
const data=ref<ConnectionList|null>(null),busy=ref(false),error=ref(''),notice=ref(''),editing=ref<Connection|null>(null),name=ref('我的 API 连接'),key=ref(''),enabled=ref(true),selected=ref(''),preview=ref('')
const empty=():ConnectionConfig=>({base_url:'https://api.anthropic.com',model:'',auth_type:'api_key',vision:'unknown',context_window:200000,role_prompt:''})
const config=ref(empty())
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){await action(async()=>{data.value=await runnerConnections.list();selected.value=data.value.default_connection_id||''})}
function edit(c:Connection,copy=false){editing.value=copy?null:c;name.value=c.name+(copy?'（副本）':'');config.value={...c.config};key.value='';enabled.value=c.enabled;preview.value=''}
function fresh(){editing.value=null;name.value='我的 API 连接';config.value=empty();key.value='';enabled.value=true}
async function save(){await action(async()=>{const saved=await runnerConnections.save({name:name.value,config:{...config.value},enabled:enabled.value,...(key.value?{api_key:key.value}:{}),...(editing.value?{expected_revision:editing.value.revision}:{})},editing.value?.id);key.value='';data.value=await runnerConnections.list();editing.value=saved;notice.value='连接已保存，API Key 不回显。修改后的连接请用于新会话；尚未调用模型验证。'})}
async function apply(){await action(async()=>{data.value=await runnerConnections.setDefault(selected.value||null,data.value!.settings_revision);notice.value='默认连接已保存，仅用于新会话；原会话保持原连接。'})}
async function check(){await action(async()=>{const c=data.value?.connections.find(c=>c.id===selected.value);const p=await runnerConnections.preview(c?{id:c.id,revision:c.revision}:null);preview.value=JSON.stringify(p.snapshot,null,2);notice.value=p.warning})}
onMounted(load)
</script>
<template><main class="connections-page"><RunnerSettingsNav/><h1>Runner · 模型连接</h1><p>仅当前账号可见。配置 Anthropic Messages 兼容 API；OpenAI 格式地址需要兼容网关。保存和预检均不调用模型。</p>
 <p v-if="error" role="alert" class="error">{{ error }} <button :disabled="busy" @click="load">重新载入</button></p><p role="status">{{ notice }}</p>
 <template v-if="data"><section><h2>新会话默认连接</h2><label>连接<select v-model="selected" :disabled="busy"><option v-if="data.legacy_available" value="">保留现有管理员连接</option><option v-else disabled value="">请先配置自己的 API</option><option v-for="c in data.connections" :key="c.id" :value="c.id" :disabled="!c.enabled">{{ c.name }} · {{ c.config.model }} · v{{ c.revision }}</option></select></label><div><button :disabled="busy" @click="apply">保存默认连接</button><button :disabled="busy" @click="check">配置预检（不调用模型）</button></div><pre v-if="preview">{{ preview }}</pre><p>已有会话不会切换服务商。连接修订或停用后，绑定它的会话需使用新会话继续；不会回退其他账号或宿主机密钥。</p></section>
 <section><h2>我的连接</h2><p v-if="!data.connections.length">还没有自定义连接。</p><article v-for="c in data.connections" :key="c.id"><strong>{{ c.name }}</strong> · {{ c.enabled?'启用':'停用' }} · v{{ c.revision }}<p>{{ c.config.base_url }} · {{ c.config.model }}</p><p>{{ c.has_credential?'凭据已加密保存':'尚无凭据' }} · 能力未经真实验证</p><button :disabled="busy" @click="edit(c)">编辑</button><button :disabled="busy" @click="edit(c,true)">复制（不含密钥）</button></article><button :disabled="busy" @click="fresh">新建连接</button></section>
 <section><h2>{{ editing?'编辑连接':'新建连接' }}</h2><form @submit.prevent="save"><label>名称<input v-model="name" maxlength="80" required /></label><label>API 根地址<input v-model="config.base_url" type="url" maxlength="500" required placeholder="https://example.com/anthropic" /></label><small>默认仅允许公网 HTTPS；内网服务需管理员配置允许列表。</small><label>鉴权方式<select v-model="config.auth_type"><option value="api_key">x-api-key</option><option value="bearer">Bearer Token</option></select></label><label>{{ editing?'API Key（留空保留原值）':'API Key' }}<input v-model="key" type="password" autocomplete="new-password" :required="!editing" maxlength="4096" /></label><label>准确模型名称<input v-model="config.model" required maxlength="150" placeholder="服务商提供的模型标识" /></label><label>图片理解能力<select v-model="config.vision"><option value="unknown">未知，禁止发送图片</option><option value="declared_yes">服务商声明支持（尚未验证）</option><option value="declared_no">不支持</option></select></label><label>声明上下文容量（token）<input v-model.number="config.context_window" type="number" min="4096" max="1000000" required /></label><small>填写 1,000,000 只记录声明，不保证模型实际支持，也不改变模型名称或自动启用付费能力。</small><label>研究角色补充要求<textarea v-model="config.role_prompt" rows="4" maxlength="6000" placeholder="例如：优先核对实验依据，并区分推测与论文原文。" /></label><label class="inline"><input type="checkbox" v-model="enabled" />启用此连接</label><p>角色不会增加工具或论文访问权限。修改连接将增加版本；新会话使用新版本。</p><button type="submit" :disabled="busy||!name.trim()">{{ busy?'保存中…':'保存连接' }}</button></form></section></template></main></template>
<style scoped>.connections-page{height:100%;overflow:auto;box-sizing:border-box;padding:28px;max-width:1100px;margin:auto;line-height:1.6}.connections-page section{border:1px solid var(--border,#ddd);border-radius:var(--radius-panel);background:var(--bg);padding:20px;margin:18px 0}.connections-page form{display:grid;gap:14px;max-width:680px}.connections-page label{display:grid;gap:6px}.connections-page input,.connections-page select,.connections-page textarea{padding:9px;max-width:100%;box-sizing:border-box}.connections-page article{padding:12px 0;border-bottom:1px solid var(--border,#ddd)}.connections-page button{padding:7px 12px;margin:8px 8px 0 0}.connections-page pre{white-space:pre-wrap;overflow-wrap:anywhere}.connections-page .inline{display:flex;align-items:center}.error{color:var(--danger)}</style>
